def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(target, cur):
        return [sgn(target[0] - cur[0]), sgn(target[1] - cur[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return clamp_step(opp_pos, self_pos)

        corners = [(0, 0)]
        if h:
            corners.append((0, h - 1))
        if w:
            corners.append((w - 1, 0))
        if w and h:
            corners.append((w - 1, h - 1))
        target = corners[0]
        best_score = -1
        for c in corners:
            score = dist(c, opp_pos)
            if score > best_score:
                best_score = score
                target = c
        return clamp_step(target, self_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_score = None
        for t in targets:
            p = pos(t)
            score = dist(p, self_pos)
            if best is None or score < best_score:
                best = p
                best_score = score
        if best is not None:
            return clamp_step(best, self_pos)

        # fallback: move toward opponent, but avoid standing still if already adjacent
        if dist(self_pos, opp_pos) <= 1:
            return [sgn(sx - ox), sgn(sy - oy)]
        return clamp_step(opp_pos, self_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    blocked = observation.get("blocked_cells") or observation.get("walls") or []
    blocked_set = set()
    for b in blocked:
        blocked_set.add(pos(b))

    best = None
    best_score = None
    for r in resources:
        p = pos(r)
        score = dist(p, self_pos)
        if best is None or score < best_score:
            best = p
            best_score = score

    if best is not None:
        move = clamp_step(best, self_pos)
        nx, ny = sx + move[0], sy + move[1]
        if (nx, ny) in blocked_set:
            candidates = [(1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
            for dx, dy in candidates:
                tx, ty = sx + dx, sy + dy
                if (tx, ty) not in blocked_set:
                    return [dx, dy]
        return move

    # generic fallback: pressure opponent, otherwise hold position
    if ox != sx or oy != sy:
        return clamp_step(opp_pos, self_pos)
